package com.trampolim.api.education;
import java.util.*;import java.time.*;import com.trampolim.api.career.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.HttpStatus;
@RestController @ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class LearningRegionalController {
 private final JdbcTemplate jdbc;private final LearningAccess access;private final RadarBridge bridge;
 public LearningRegionalController(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,RadarBridge bridge){this.jdbc=jdbc;this.access=access;this.bridge=bridge;}
 @GetMapping("/api/capacita/learning/observatory/consent")public List<Map<String,Object>> consent(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT region_code,consent_at FROM learning_observatory_consents WHERE student_id=?",access.account(email).id());}
 @PutMapping("/api/capacita/learning/observatory/consent")@ResponseStatus(HttpStatus.NO_CONTENT)public void consent(@AuthenticationPrincipal String email,@RequestBody CareerRegionalController.Consent input){if(input==null||!input.consent())RadarModel.bad("Autorize contagens regionais de aprendizagem e participação em programas.");jdbc.update("INSERT INTO learning_observatory_consents(student_id,region_code) VALUES (?,?) ON CONFLICT(student_id) DO UPDATE SET region_code=EXCLUDED.region_code,consent_at=CURRENT_TIMESTAMP",access.account(email).id(),CareerRules.region(input.regionCode(),false));}
 @DeleteMapping("/api/capacita/learning/observatory/consent")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email){jdbc.update("DELETE FROM learning_observatory_consents WHERE student_id=?",access.account(email).id());}
 @PostMapping("/api/integrations/career/observatory/learning")public Map<String,Object> aggregate(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CareerRegionalController.Query input){bridge.authorize(key);CareerRegionalController.validate(input);String region=CareerRules.region(input.region(),true);Object[] args={region,region,LocalDate.parse(input.from()),LocalDate.parse(input.to()).plusDays(1)};String cohort="WITH cohort AS (SELECT c.student_id FROM learning_observatory_consents c JOIN student_users u ON u.id=c.student_id AND u.account_status='ACTIVE' AND u.email_verified=TRUE WHERE (?='' OR c.region_code=?) AND c.consent_at>=? AND c.consent_at<?) ";long participants=jdbc.queryForObject(cohort+"SELECT count(*) FROM cohort",Long.class,args);var result=new LinkedHashMap<String,Object>();result.put("participants",CareerRules.band(participants));if(participants<10){result.put("courseCompletions",CareerRules.band(0));result.put("programParticipants",CareerRules.band(0));return result;}
  String done=cohort+", lessons AS (SELECT h.student_id,c.id AS course_id,count(l.id) AS total,count(p.completed_at) AS completed FROM cohort h JOIN learning_lesson_progress p ON p.student_id=h.student_id JOIN learning_lessons l ON l.id=p.lesson_id AND l.status='PUBLISHED' AND l.validation_status='READY' JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id JOIN learning_courses c ON c.id=s.course_id AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE JOIN student_users teacher ON teacher.id=c.teacher_id AND teacher.account_status='ACTIVE' GROUP BY h.student_id,c.id), valid AS (SELECT x.student_id,x.course_id FROM lessons x WHERE x.completed=(SELECT count(*) FROM learning_lessons l JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id WHERE s.course_id=x.course_id AND l.status='PUBLISHED' AND l.validation_status='READY') AND NOT EXISTS(SELECT 1 FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id WHERE a.course_id=x.course_id AND a.status='PUBLISHED' AND (v.definition->>'requiredForCompletion')::boolean=TRUE AND NOT EXISTS(SELECT 1 FROM learning_assessment_attempts t WHERE t.student_id=x.student_id AND t.assessment_id=a.id AND t.passed=TRUE))) SELECT count(*) AS completions,count(DISTINCT student_id) AS contributors FROM valid";var counts=jdbc.queryForMap(done,args);result.put("courseCompletions",((Number)counts.get("contributors")).longValue()<10?CareerRules.band(0):CareerRules.band(((Number)counts.get("completions")).longValue()));
  long programs=0;if(!input.publicPrograms().isEmpty()){var programArgs=new ArrayList<Object>(Arrays.asList(args));programArgs.addAll(input.publicPrograms());programs=jdbc.queryForObject(cohort+"SELECT count(DISTINCT p.student_id) FROM cohort c JOIN hub_program_participations p ON p.student_id=c.student_id WHERE p.program_id IN ("+String.join(",",Collections.nCopies(input.publicPrograms().size(),"?"))+")",Long.class,programArgs.toArray());}result.put("programParticipants",CareerRules.band(programs));result.put("notice","Coorte regional com consentimento específico, não todos os alunos da região. Conclusões são a situação atual dos cursos dessa coorte, não uma série histórica de certificações.");return result;}
}
